import itertools

def solve_small_n(n):
    m = n * (n - 1) // 2
    edges = list(itertools.combinations(range(n), 2))
    min_cost = float('inf')

    for p in itertools.permutations(range(1, m + 1)):
        # p[i] is the index of the i-th edge
        # No, p is a permutation of 1..m. 
        # Let's say p[i] is the index assigned to edges[i].
        # cost = sum over v of (max(p[i] for i where v in edges[i]) - min(p[i] for i where v in edges[i]))

        current_cost = 0
        for v in range(n):
            indices = []
            for i, edge in enumerate(edges):
                if v in edge:
                    indices.append(p[i])
            current_cost += max(indices) - min(indices)

        if current_cost < min_cost:
            min_cost = current_cost

    return n + min_cost

