    min_cost = float('inf')
    # The edges of K_n can be mapped to 0..m-1
    # There are m! permutations. For n=4, m=6, m!=720.
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j))

    for p in itertools.permutations(range(1, m + 1)):
        # p is a permutation of 1..m
        # Assign p[k] to edges[k]
        assignment = {}
        for k in range(m):
            assignment[edges[k]] = p[k]

        total_cost = 0
        for i in range(n):
            s_i = []
            for j in range(n):
                if i != j:
                    u, v = (i, j) if i < j else (j, i)
                    s_i.append(assignment[(u, v)])
            total_cost += max(s_i) - min(s_i) + 1

        if total_cost < min_cost:
            min_cost = total_cost
    return min_cost

