def solve(n):
    M = n * (n - 1) // 2
    min_cost = float('inf')

    # We need to find m_j and M_j
    # There are only a few possibilities for each j

    def backtrack(j, current_U, current_S, current_m, current_M):
        nonlocal min_cost
        if j == M + 1:
            if current_U == 0 and current_S == 0:
                cost = sum(k * current_M[k-1] for k in range(1, M+1)) - \
                       sum(k * current_m[k-1] for k in range(1, M+1)) + n
                if cost < min_cost:
                    min_cost = cost
            return

        for m in range(3):
            for M_val in range(3):
                if m + M_val <= 2 and m <= current_U and M_val <= current_S:
                    current_m.append(m)
                    current_M.append(M_val)
                    backtrack(j + 1, current_U - m, current_S + m - M_val, current_m, current_M)
                    current_m.pop()
                    current_M.pop()

    # This is too slow. Let's use dynamic programming.
    # dp[j][U][S] = min cost
    # But the cost depends on the values of m_k and M_k.
    # The cost is sum(k*M_k) - sum(k*m_k) + n.
    # So we can keep track of the current sum.

    # dp[j][U][S] = min value of sum_{k=1}^j (k*M_k - k*m_k)
    # where j is the day, U is current_U, S is current_S

    # Wait, the state should be dp[j][U][S]
    dp = {} # (j, U, S) -> min_cost_sum
    dp[(0, n, 0)] = 0

    for j in range(1, M + 1):
        new_dp = {}
        for (prev_j, U, S), cost_sum in dp.items():
            for m in range(3):
                for M_val in range(3):
                    if m + M_val <= 2 and m <= U and M_val <= S:
                        new_U = U - m
                        new_S = S + m - M_val
                        new_cost = cost_sum + j * M_val - j * m
                        state = (j, new_U, new_S)
                        if state not in new_dp or new_cost < new_dp[state]:
                            new_dp[state] = new_cost
        dp = new_dp

    return dp.get((M, 0, 0), float('inf')) + n

