    cost = 0
    for i in range(n):
        cost += max(player_matches[i]) - min(player_matches[i]) + 1
    return cost

def solve_hill_climbing(n, iterations=10000):
    edges = list(itertools.combinations(range(n), 2))
    best_cost = float('inf')
    for _ in range(50):
        p = list(edges)
        random.shuffle(p)
        current_cost = calculate_cost(n, p)
        for _ in range(iterations):
            i, j = random.sample(range(len(p)), 2)
            p[i], p[j] = p[j], p[i]
            new_cost = calculate_cost(n, p)
            if new_cost < current_cost:
                current_cost = new_cost
            else:
                p[i], p[j] = p[j], p[i]
        if current_cost < best_cost:
            best_cost = current_cost
    return best_cost

