    M = n * (n - 1) // 2
    mp = [min_players(j) for j in range(1, M + 1)]
    A = [max(mp[j-1], n - 2*(M-j)) for j in range(1, M+1)]
    E = [max(mp[M-j], n - 2*(j-1)) for j in range(1, M+1)]
    total_sum = 0
    for j in range(1, M+1):
        total_sum += max(A[j-1] + E[j-1], n+2)
    return total_sum - M * n

